{"data":"
flowchart TD
    A["Operator<br/>Runs the larkdocio download command"] --> B["Resolve the URL<br/>Classify the host and the token kind: Document"]
    B --> C["Pick the reader:<br/>Docx document"]

    C --> D["Step 1: Fetch metadata<br/>Includes title, revision id,<br/>block count, display settings,<br/>and the parent folder and its space,<br/>checked before any block is read"]

    D --> E["Step 2: List blocks<br/>Includes pagination and the child order"]

    E --> F["Step 3: Render all"]
    F --> F1["Text & Heading blocks<br/>Includes inline styles and links"]
    F --> F2["Media blocks<br/>Download or skip each image<br/>Asset folder: ./assets"]

    F1 --> G["Step 4: Write<br/>Write the Markdown file"]
    F2 --> G

    G --> H{"Check result"}
    H -->|Dry run requested| I["Summary of a dry run<br/>Show the planned files without writing them"]

    H -->|Write files| J{"Write outcome"}
    J -->|Write failed| K["Errors from writing<br/>Show the failing block and its error"]
    J -->|Write succeeded| L["Done, all written<br/>Show the written Markdown path"]

    classDef step fill:#E8F3FF,stroke:#2F80ED,stroke-width:1.5px,color:#1F2937;
    classDef decision fill:#FFF7E6,stroke:#F59E0B,stroke-width:1.5px,color:#1F2937;

    class A,B,C,D,E,F,F1,F2,G,I,K,L step;
    class H,J decision;

","theme":"default","view":"codeChart"}

